import {
  Component, ChangeDetectionStrategy, inject,
  output, computed
} from '@angular/core';
import { LogsService } from '../services/logs.service';
import { LogStatus } from '../models/log.model';

@Component({
  selector: 'app-log-detail',
  standalone: true,
  imports: [],
  templateUrl: './log-detail.html',
  styleUrl: './log-detail.scss',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class LogDetailComponent {
  private logsService = inject(LogsService);

  // Signals from service
  readonly logDetail = this.logsService.selectedLog;
  readonly logText = this.logsService.selectedLogText;
  readonly loading = this.logsService.loading;

  // Outputs
  closed = output<void>();
  viewPayload = output<number>();

  // Computed values
  readonly log = computed(() => this.logDetail()?.log);
  readonly childLogs = computed(() => this.logDetail()?.child_logs ?? []);
  readonly hasPayload = computed(() => {
    const log = this.log();
    return log && log.long_text_id > 0;
  });

  onClose(): void {
    this.closed.emit();
  }

  onViewPayload(): void {
    const log = this.log();
    if (log && log.log_id) {
      this.logsService.loadLogText(log.log_id);
      this.viewPayload.emit(log.log_id);
    }
  }

  onViewChildLog(childLogId: number): void {
    this.logsService.loadLogDetail(childLogId);
  }

  getStatusClass(status: LogStatus): string {
    switch (status) {
      case 'SUCCESS': return 'status-success';
      case 'FAILED':
      case 'ERROR': return 'status-error';
      case 'IN_PROGRESS': return 'status-progress';
      case 'PARTIAL': return 'status-partial';
      default: return '';
    }
  }

  trackByLogId(index: number, log: { log_id: number }): number {
    return log.log_id;
  }
}
