import { Injectable, inject, signal, computed } from '@angular/core';
import { CclServiceWrapperService } from '../../services/ccl-service-wrapper.service';
import {
  LogEntry, LogFilters, LogsResponse, LogDetailResponse,
  LogTextResponse, DEFAULT_FILTERS
} from '../models/log.model';

@Injectable({ providedIn: 'root' })
export class LogsService {
  private cclService = inject(CclServiceWrapperService);

  // State signals
  private _logs = signal<LogEntry[]>([]);
  private _totalCount = signal(0);
  private _currentPage = signal(1);
  private _pageSize = signal(50);
  private _filters = signal<LogFilters>({ ...DEFAULT_FILTERS });
  private _loading = signal(false);
  private _error = signal<string | null>(null);
  private _selectedLog = signal<LogDetailResponse | null>(null);
  private _selectedLogText = signal<LogTextResponse | null>(null);

  // Public readonly accessors
  readonly logs = this._logs.asReadonly();
  readonly totalCount = this._totalCount.asReadonly();
  readonly currentPage = this._currentPage.asReadonly();
  readonly pageSize = this._pageSize.asReadonly();
  readonly filters = this._filters.asReadonly();
  readonly loading = this._loading.asReadonly();
  readonly error = this._error.asReadonly();
  readonly selectedLog = this._selectedLog.asReadonly();
  readonly selectedLogText = this._selectedLogText.asReadonly();

  // Computed values
  readonly totalPages = computed(() =>
    Math.ceil(this._totalCount() / this._pageSize()) || 1
  );

  readonly hasNextPage = computed(() =>
    this._currentPage() < this.totalPages()
  );

  readonly hasPrevPage = computed(() =>
    this._currentPage() > 1
  );

  /**
   * Load logs with optional filter updates
   */
  loadLogs(filters?: Partial<LogFilters>): void {
    this._loading.set(true);
    this._error.set(null);

    if (filters) {
      this.updateFilters(filters);
    }

    const currentFilters = this._filters();
    const requestData = JSON.stringify({
      ...currentFilters,
      page: this._currentPage(),
      page_size: this._pageSize()
    });

    this.cclService.load(
      {
        customScript: {
          script: [{
            name: 'gbin_mha_pds_service:group1',
            run: 'pre',
            id: 'getLogs',
            parameters: {
              requestType: 'getLogs',
              requestId: Date.now(),
              requestData: requestData
            }
          }],
          clearPatientSource: true
        }
      },
      [],
      () => {
        try {
          const response = this.cclService.get('getLogs') as LogsResponse;
          if (response) {
            this._logs.set(response.logs || []);
            this._totalCount.set(response.total_count || 0);
            this._currentPage.set(response.page || 1);
            this._pageSize.set(response.page_size || 50);
          }
        } catch (err) {
          this._error.set(err instanceof Error ? err.message : 'Failed to parse logs response');
        }
        this._loading.set(false);
      }
    );
  }

  /**
   * Load detailed information for a single log
   */
  loadLogDetail(logId: number): void {
    this._loading.set(true);
    this._error.set(null);

    const requestData = JSON.stringify({ log_id: logId });

    this.cclService.load(
      {
        customScript: {
          script: [{
            name: 'gbin_mha_pds_service:group1',
            run: 'pre',
            id: 'getLogDetail',
            parameters: {
              requestType: 'getLogDetail',
              requestId: Date.now(),
              requestData: requestData
            }
          }],
          clearPatientSource: true
        }
      },
      [],
      () => {
        try {
          const response = this.cclService.get('getLogDetail') as LogDetailResponse;
          if (response && response.found_ind) {
            this._selectedLog.set(response);
          } else {
            this._error.set('Log not found');
            this._selectedLog.set(null);
          }
        } catch (err) {
          this._error.set(err instanceof Error ? err.message : 'Failed to load log detail');
        }
        this._loading.set(false);
      }
    );
  }

  /**
   * Load JSON payload text for a log
   */
  loadLogText(logId: number): void {
    this._loading.set(true);
    this._error.set(null);

    const requestData = JSON.stringify({ log_id: logId });

    this.cclService.load(
      {
        customScript: {
          script: [{
            name: 'gbin_mha_pds_service:group1',
            run: 'pre',
            id: 'getLogText',
            parameters: {
              requestType: 'getLogText',
              requestId: Date.now(),
              requestData: requestData
            }
          }],
          clearPatientSource: true
        }
      },
      [],
      () => {
        try {
          const response = this.cclService.get('getLogText') as LogTextResponse;
          if (response && response.found_ind) {
            this._selectedLogText.set(response);
          } else {
            this._selectedLogText.set(null);
          }
        } catch (err) {
          this._error.set(err instanceof Error ? err.message : 'Failed to load log text');
        }
        this._loading.set(false);
      }
    );
  }

  /**
   * Update filter values
   */
  updateFilters(filters: Partial<LogFilters>): void {
    this._filters.update(current => ({ ...current, ...filters }));
  }

  /**
   * Reset filters to defaults
   */
  resetFilters(): void {
    this._filters.set({ ...DEFAULT_FILTERS });
    this._currentPage.set(1);
  }

  /**
   * Navigate to next page
   */
  nextPage(): void {
    if (this.hasNextPage()) {
      this._currentPage.update(p => p + 1);
      this.loadLogs();
    }
  }

  /**
   * Navigate to previous page
   */
  prevPage(): void {
    if (this.hasPrevPage()) {
      this._currentPage.update(p => p - 1);
      this.loadLogs();
    }
  }

  /**
   * Navigate to specific page
   */
  goToPage(page: number): void {
    if (page >= 1 && page <= this.totalPages()) {
      this._currentPage.set(page);
      this.loadLogs();
    }
  }

  /**
   * Clear selected log and text
   */
  clearSelectedLog(): void {
    this._selectedLog.set(null);
    this._selectedLogText.set(null);
  }
}
