import { Component, ChangeDetectionStrategy, inject, output } from '@angular/core';
import { LogsService } from '../services/logs.service';
import { LogEntry, LogStatus } from '../models/log.model';

@Component({
  selector: 'app-log-table',
  standalone: true,
  imports: [],
  templateUrl: './log-table.html',
  styleUrl: './log-table.scss',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class LogTableComponent {
  private logsService = inject(LogsService);

  // Expose service signals to template
  readonly logs = this.logsService.logs;
  readonly loading = this.logsService.loading;
  readonly error = this.logsService.error;
  readonly totalCount = this.logsService.totalCount;
  readonly currentPage = this.logsService.currentPage;
  readonly totalPages = this.logsService.totalPages;
  readonly hasNextPage = this.logsService.hasNextPage;
  readonly hasPrevPage = this.logsService.hasPrevPage;

  // Output for row selection
  logSelected = output<LogEntry>();

  onSelectLog(log: LogEntry): void {
    this.logSelected.emit(log);
    this.logsService.loadLogDetail(log.log_id);
  }

  onNextPage(): void {
    this.logsService.nextPage();
  }

  onPrevPage(): void {
    this.logsService.prevPage();
  }

  getStatusClass(status: LogStatus): string {
    switch (status) {
      case 'SUCCESS': return 'status-success';
      case 'FAILED':
      case 'ERROR': return 'status-error';
      case 'IN_PROGRESS': return 'status-progress';
      case 'PARTIAL': return 'status-partial';
      default: return '';
    }
  }

  formatDuration(seconds: number): string {
    if (!seconds || seconds === 0) {
      return '-';
    } else if (seconds < 60) {
      return `${seconds}s`;
    } else if (seconds < 3600) {
      const mins = Math.floor(seconds / 60);
      const secs = seconds % 60;
      return `${mins}m ${secs}s`;
    } else {
      const hours = Math.floor(seconds / 3600);
      const mins = Math.floor((seconds % 3600) / 60);
      return `${hours}h ${mins}m`;
    }
  }

  trackByLogId(index: number, log: LogEntry): number {
    return log.log_id;
  }
}
