/**
 * TypeScript interfaces for MHA PDS log data structures
 */

export type LogType = 'MANAGER' | 'DATA_EXTRACTION' | 'TRANSMISSION' | 'MIRTH_CALLBACK';

export type LogStatus = 'IN_PROGRESS' | 'SUCCESS' | 'FAILED' | 'ERROR' | 'PARTIAL';

export interface LogEntry {
  log_id: number;
  log_type: LogType;
  title: string;
  summary: string;
  related_script: string;
  function_name: string;
  start_dt_tm: string;
  start_dt_tm_formatted: string;
  stop_dt_tm: string;
  stop_dt_tm_formatted: string;
  duration_seconds: number;
  status: LogStatus;
  person_id: number;
  encntr_id: number;
  episode_id: number;
  service_id: number;
  batch_id: string;
  has_payload: number;
  record_cnt: number;
  error_cnt: number;
  error_message: string;
  parent_log_id: number;
}

export interface LogFilters {
  log_type: LogType | '';
  status: LogStatus | '';
  start_date: string;
  end_date: string;
  related_script: string;
  days_back: number;
  page: number;
  page_size: number;
}

export interface LogsResponse {
  total_count: number;
  returned_count: number;
  page: number;
  page_size: number;
  filters_applied: LogFilters;
  logs: LogEntry[];
}

export interface LogDetail extends LogEntry {
  long_text_id: number;
  duration_formatted: string;
  active_ind: number;
  create_dt_tm: string;
  create_dt_tm_formatted: string;
  create_prsnl_id: number;
  create_prsnl_name: string;
  updt_dt_tm: string;
  updt_dt_tm_formatted: string;
  updt_prsnl_id: number;
  updt_prsnl_name: string;
  updt_cnt: number;
}

export interface LogDetailResponse {
  found_ind: number;
  log: LogDetail;
  child_log_cnt: number;
  child_logs: ChildLog[];
}

export interface ChildLog {
  log_id: number;
  log_type: LogType;
  title: string;
  status: LogStatus;
  start_dt_tm_formatted: string;
}

export interface LogTextResponse {
  found_ind: number;
  log_id: number;
  long_text_id: number;
  text_length: number;
  text_content: string;
  content_type: string;
  is_json: number;
}

export const DEFAULT_FILTERS: LogFilters = {
  log_type: '',
  status: '',
  start_date: '',
  end_date: '',
  related_script: '',
  days_back: 7,
  page: 1,
  page_size: 50
};

