import {
  Component, ChangeDetectionStrategy, inject,
  output, computed, signal
} from '@angular/core';
import { DecimalPipe } from '@angular/common';
import { LogsService } from '../services/logs.service';

@Component({
  selector: 'app-payload-viewer',
  standalone: true,
  imports: [DecimalPipe],
  templateUrl: './payload-viewer.html',
  styleUrl: './payload-viewer.scss',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class PayloadViewerComponent {
  private logsService = inject(LogsService);

  // Signals from service
  readonly logText = this.logsService.selectedLogText;
  readonly loading = this.logsService.loading;

  // Local state
  readonly viewMode = signal<'formatted' | 'raw'>('formatted');
  readonly copySuccess = signal(false);

  // Outputs
  closed = output<void>();

  // Computed values
  readonly hasContent = computed(() => {
    const text = this.logText();
    return text && text.found_ind && text.text_content;
  });

  readonly formattedContent = computed(() => {
    const text = this.logText();
    if (!text || !text.text_content) return '';

    if (text.is_json) {
      try {
        const parsed = JSON.parse(text.text_content);
        return JSON.stringify(parsed, null, 2);
      } catch {
        return text.text_content;
      }
    }
    return text.text_content;
  });

  readonly rawContent = computed(() => {
    const text = this.logText();
    return text?.text_content ?? '';
  });

  readonly displayContent = computed(() => {
    return this.viewMode() === 'formatted'
      ? this.formattedContent()
      : this.rawContent();
  });

  readonly contentInfo = computed(() => {
    const text = this.logText();
    if (!text) return null;
    return {
      length: text.text_length,
      type: text.content_type,
      isJson: text.is_json
    };
  });

  onClose(): void {
    this.closed.emit();
  }

  setViewMode(mode: 'formatted' | 'raw'): void {
    this.viewMode.set(mode);
  }

  async copyToClipboard(): Promise<void> {
    try {
      await navigator.clipboard.writeText(this.displayContent());
      this.copySuccess.set(true);
      setTimeout(() => this.copySuccess.set(false), 2000);
    } catch (err) {
      console.error('Failed to copy:', err);
    }
  }

  onOverlayClick(event: MouseEvent): void {
    // Only close if clicking on the overlay itself, not the modal
    if (event.target === event.currentTarget) {
      this.onClose();
    }
  }
}
