import { Component, ChangeDetectionStrategy, inject, OnInit, signal } from '@angular/core';
import { LogsService } from './services/logs.service';
import { LogFiltersComponent } from './components/log-filters';
import { LogTableComponent } from './components/log-table';
import { LogDetailComponent } from './components/log-detail';
import { PayloadViewerComponent } from './components/payload-viewer';
import { LogEntry } from './models/log.model';

/**
 * Logs component for viewing and searching MHA PDS operational logs
 */
@Component({
  selector: 'app-logs',
  standalone: true,
  imports: [
    LogFiltersComponent,
    LogTableComponent,
    LogDetailComponent,
    PayloadViewerComponent
  ],
  templateUrl: './logs.html',
  styleUrl: './logs.scss',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class LogsComponent implements OnInit {
  private logsService = inject(LogsService);

  // Expose service signals for template
  readonly selectedLog = this.logsService.selectedLog;
  readonly selectedLogText = this.logsService.selectedLogText;
  readonly loading = this.logsService.loading;

  // Local state
  readonly showDetail = signal(false);
  readonly showPayload = signal(false);

  ngOnInit(): void {
    // Load logs with default filters on mount
    this.logsService.loadLogs();
  }

  onLogSelected(log: LogEntry): void {
    this.showDetail.set(true);
  }

  onCloseDetail(): void {
    this.showDetail.set(false);
    this.logsService.clearSelectedLog();
  }

  onViewPayload(logId: number): void {
    this.showPayload.set(true);
  }

  onClosePayload(): void {
    this.showPayload.set(false);
  }
}
