import { Component, ChangeDetectionStrategy, inject } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { LogsService } from '../services/logs.service';
import {
  LogFilters, LogType, LogStatus,
  LOG_TYPE_OPTIONS, LOG_STATUS_OPTIONS
} from '../models/log.model';

@Component({
  selector: 'app-log-filters',
  standalone: true,
  imports: [FormsModule],
  templateUrl: './log-filters.html',
  styleUrl: './log-filters.scss',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class LogFiltersComponent {
  private logsService = inject(LogsService);

  // Filter options
  readonly logTypeOptions = LOG_TYPE_OPTIONS;
  readonly statusOptions = LOG_STATUS_OPTIONS;

  // Current filter values (bound to form)
  selectedLogType: LogType | '' = '';
  selectedStatus: LogStatus | '' = '';
  startDate: string = '';
  endDate: string = '';
  relatedScript: string = '';
  daysBack: number = 7;

  onApplyFilters(): void {
    const filters: LogFilters = {
      log_type: this.selectedLogType,
      status: this.selectedStatus,
      start_date: this.startDate,
      end_date: this.endDate,
      related_script: this.relatedScript,
      days_back: this.daysBack,
      page: 1,
      page_size: 50
    };
    this.logsService.loadLogs(filters);
  }

  onResetFilters(): void {
    this.selectedLogType = '';
    this.selectedStatus = '';
    this.startDate = '';
    this.endDate = '';
    this.relatedScript = '';
    this.daysBack = 7;
    this.logsService.resetFilters();
    this.logsService.loadLogs();
  }
}
